create procedure [dbo].[cgRSLogRango]
 @desde datetime,
 @hasta datetime,
 @usuario varchar(30)
as
 select * from cgGenEDLog
 where fecha between @desde and @hasta
 and (isnull(@usuario,'') = '' or Usuario = @usuario)
 order by fecha, EntradaNumero, Referencia
return 0

