CREATE  PROCEDURE [dbo].[nomAutoViatico]
  @NominaID Int
AS
DECLARE
  @TipoEmpleadoID int,
  @NominaDias numeric(18,2),
  @DiaFeriado numeric(18,2),
  @SalDiasPor Numeric(18,4),
  @FechaInicial datetime,
  @FechaFinal datetime,
  @UltNominaMes Bit,
  @Ano Int,
  @Mes Int,
  @SueldoPorTiempo Int,
  @nomTransViatico Int

SELECT 
	@NominaDias = TipoNomina.Dias, 
	@DiaFeriado = Nomina.DiaFeriado,   
	@TipoEmpleadoID = Nomina.TipoEmpleadoID,
	@SalDiasPor = TipoNomina.SalDiasPor,
        @FechaInicial = Nomina.Desde,
        @FechaFinal = Nomina.Hasta,
        @UltNominaMes = ISR,
        @Ano = Year(Nomina.Fecha),
        @Mes = Nomina.MesCalendario
FROM 
	Nomina INNER JOIN TipoNomina ON Nomina.TipoNominaID = TipoNomina.TipoNominaID 
WHERE 
	NominaID = @NominaID

Set
  @nomTransViatico = IsNull((Select Convert(Int, Valor) From Defaults Where Clave = 'nomTransViatico'),0)

  INSERT INTO Transaccion(NominaID, EmpleadoID, TipoTransaccionID, Transaccion, xCantidad, Notas, Calculada, Modificada, IdCentroCosto, CentroCosto)
    SELECT  
	@NominaID, 
	E.EmpleadoID, 
	@nomTransViatico, -- tipo de transaccion para viatico
	e.Viatico,
	0,
	'Auto Generado',
	0,
	0,
        cc.IdCentroCosto,
        cc.CentroCosto
     FROM       
	Empleado E Inner Join
        Seccion se On (se.SeccionId = e.SecionId) Left Outer Join
        CentroCosto cc On (cc.IdCentroCosto = se.uSeccion)
     WHERE     
	E.TipoEmpleadoID = @TipoEmpleadoID 
	and E.Activo=1
	and (isnull(E.fin, @FechaInicial) >= @FechaInicial) 
        and (e.inicio <= @FechaFinal)
	and (E.HorasDia*(@NominaDias)) > 0
        and (@nomTransViatico > 0)
        and e.Viatico > 0
	and not exists (Select top 1 1 
	                from transaccion ttx 
	                where ttx.EmpleadoID = e.EmpleadoID and ttx.nominaid = @NominaID and ttx.TipoTransaccionid = @nomTransViatico)

CREATE   procedure [dbo].[cxcDatosEstado]  ---19982,'20181231','00000893'
 --declare
 @idCli int,   
 @Fec DATETIME,
 @idDir varchar(30) = null
 as  
 --set @idcli=19982
 --set @fec='20181231'
 --set @idDir='00000893'
declare   
 @Bal decimal(19,2) ,  
 @PorDist decimal(19,2),  
 @FechaUltCargo datetime ,  
 @RefUltCargo varchar(20) ,    
 @TipoUltCargo varchar(10) ,  
 @MtoUltCargo decimal(19,2) ,  
 @FechaUltPago datetime ,  
 @RefUltPago varchar(20) ,   
 @MtoUltPago decimal(19,2),   
 @Abono decimal(19,2)
--as  
 
 set @Bal = dbo.cxcBalanceCliente(@idCli, @Fec)  
  
 set @PorDist = dbo.cxcCreditoporDist(@idCli, @Fec)  
  
 select top 1
		 	   
		 @FechaUltCargo = f.Fecha,  
		 @RefUltCargo = f.CXC,  
		 @TipoUltCargo = f.idTipoDocumento,  
		 @MtoUltCargo = f.Valor  
  from CXC f   
where  f.idCliente = @idCli and f.Fecha <= @Fec  
 and f.esCredito = 0
 and (@idDir is null or f.idClienteObra = @idDir)   
 order by f.fecha desc, f.CXC desc   
  
 select top 1   
		 @FechaUltPago = r.Fecha,  
		 @RefUltPago = r.CXC,  
		 @MtoUltPago = r.Valor  
  from CXC r   
where  EsCredito = 1  
 and r.idCliente = @idCli   
 and r.Fecha <= @Fec   
 order by fecha desc, CXC desc   

 select 
 @Abono= sum(r.Valor)
   from CXC r   
where  EsCredito = 1  
 and r.idCliente = @idCli   
 and r.Fecha <= @Fec --and (@idDir is null or r.CxC = @idDir)   
 --order by fecha desc, CXC desc   
  
select  @idCli as idCliente,
		@Bal as Balance,   
        @PorDist as PorDist,  
		@FechaUltCargo as FecUltCargo,  
		@RefUltCargo as RefUltCargo,    
		@TipoUltCargo as TipoUltCargo,   
		@MtoUltCargo as MtoUltCargo,  
		@FechaUltPago as FecUltPago,  
		@RefUltPago as RefUltPago,   
		@MtoUltPago as MtoUltPago,  
		@Abono as Abono 
return 0

