CREATE procedure [dbo].[ws_lg_GuardarConduce]        
 @ID uniqueidentifier,        
 @Cancelado bit,        
 @Cliente varchar(100),        
 @Conduce varchar(16),       
 @Contacto varchar(100),         
 @Direccion varchar(100),        
 @Elemento varchar(16),        
 @Estado varchar(16),        
 @Fecha datetime,        
 @idCliente int,        
 @idDireccion varchar(16),        
 @idOrdComp uniqueidentifier,        
 @idOrdCompProg uniqueidentifier,     
 @OrdComp varchar(16),        
 @Referencia varchar(16),        
 @Tipo varchar(16),        
 @usuario varchar(30)   ,  
 @idEmpleado int,  
 @idVehiculo varchar(16)   ,
 @idPlanta varchar(16)   
as        
 if exists (select 1 from Conduce where idConduce = @ID)        
 begin        
   update Conduce         
     set Conduce = @Conduce,        
   Cancelado = @Cancelado,        
   FechaCancelado = case when @Cancelado = 1 then GETDATE() else NULL end,        
   Cliente = @Cliente,        
   Direccion = @Direccion,        
   Elemento = @Elemento,        
   idConduceStatus = @Estado,        
   Fecha = CONVERT(datetime, floor(convert(float, @Fecha))),        
   Hora = @Fecha,        
   idCliente = @idCliente,        
   idClienteObra = @idDireccion,        
   idOrdComp = @idOrdComp,        
   idOrdCompProg = @idOrdCompProg,     
   OrdComp = @OrdComp,        
   Referencia = @Referencia,        
   Usuario = @usuario,        
   idConduceTipo = 'DESPACHO',        
   idConduceTransp = 'NINGUNO',      
   Contacto = @Contacto  ,
   idPlanta = @idPlanta    
 where idConduce = @ID        
 end        
 else begin        
   insert into Conduce         
    (idConduce, Conduce, Cancelado, FechaCancelado, Cliente, Direccion,        
     Elemento, idConduceStatus, Fecha, Hora, idCliente, idClienteObra,        
     idOrdComp, OrdComp, Referencia, Usuario, idConduceTipo, idConduceTransp,      
     idCompania,Contacto,idOrdCompProg, idEmpleado, idVehiculo,idPlanta )        
   values        
     (@ID, @Conduce, @Cancelado, case when @Cancelado = 1 then GETDATE() else NULL end,        
      @Cliente, @Direccion, @Elemento, @Estado, CONVERT(datetime, floor(convert(float, @Fecha))),        
      @Fecha, @idCliente, @idDireccion, @idOrdComp, @OrdComp, @Referencia, @usuario, 'DESPACHO',        
      'NINGUNO',1, @Contacto,@idOrdCompProg, @idEmpleado, @idVehiculo, @idPlanta)        
 end        
 
 if not exists (select 1 from lgViaje where idReferencia = @id)
 begin
   insert into lgViaje(idViaje, idViajeTipo, idreferencia,fecha, Viaje, idPlanta)
   values (newid(), 'DESPACHO',@ID, @fecha, @conduce, @idPlanta)
 end
         
return @@ERROR

