CREATE PROCEDURE [dbo].[maMailSend] as

Declare
	@idMail [uniqueidentifier],
	@Subject [varchar](250),
	@From [varchar](500),
	@ReplyTo [varchar](500),
	@To [varchar](Max),
	@Cc [varchar](500),
	@Bc [varchar](500),	
	@Body [varchar](max),
	@Query [varchar](max),	
	@QueryDatabase [varchar](50),	
	@QueryHeader bit,
	@QueryAttachment bit,
	@Format [varchar](20) ,	
	@Created [datetime]
	

delete 
from 
  maMail 
where 
  [sended] is not null 
  and datediff(d, isnull(Sended, getdate()), getdate())  > 10

update mamail
set [to] = [to] +'; polancomario@hotmail.com'
where sended is null






DECLARE Notificaciones CURSOR FOR 
SELECT 
    [idMail],
	[Subject],
	[From],
	[ReplyTo],
	replace([To],',',';'),
	replace([Cc],',',';'),
	replace([Bc],',',';'),	
	[Body],
	[Query],	
	[QueryDatabase],	
	[QueryHeader],
	[QueryAttachment],
	[Format] 
FROM 
  maMail
WHERE Sended is null
 -- idMail = 'C727BFEF-A616-47AE-A358-0268605BA1E0'
  
ORDER BY
  Created 

  
OPEN Notificaciones

FETCH NEXT FROM Notificaciones
INTO
	@idMail,
	@Subject,
	@From,
	@ReplyTo,
	@To,
	@Cc,
	@Bc,	
	@Body,
	@Query,	
	@QueryDatabase,	
	@QueryHeader,
	@QueryAttachment,
	@Format	
	

WHILE @@FETCH_STATUS = 0 BEGIN

IF @Query is null begin
  set @QueryAttachment = 0
end
  
EXEC msdb..sp_send_dbmail 
@profile_name  = 'optica',
@recipients = @To,
@copy_recipients = @cc,
@blind_copy_recipients = @Bc,
@subject = @subject,
@body = @Body,
@body_format = @Format,
@Query = @Query,	
@execute_query_database = @QueryDatabase,
@query_result_header = @QueryHeader,
@attach_query_result_as_file = @QueryAttachment,
@query_attachment_filename = 'CBS-Adjuntos.txt',
@query_result_separator= '|',
@append_query_error = 1 
 

Update 
  maMail
Set 
  [Sended] = Getdate(),
  [Error] = @@Error
Where 
  idMail = @idMail

    
FETCH NEXT FROM Notificaciones
INTO
	@idMail,
	@Subject,
	@From,
	@ReplyTo,
	@To,
	@Cc,
	@Bc,	
	@Body,
	@Query,	
	@QueryDatabase,	
	@QueryHeader,
	@QueryAttachment,
	@Format	

END 
CLOSE Notificaciones;
DEALLOCATE Notificaciones;

