CREATE PROCEDURE [dbo].[ContContratoResumen](@idContrato uniqueidentifier) AS
Declare
--  @idContrato uniqueidentifier,
  @Comprometido decimal(18,2),
  @Avanzado     decimal(18,2),
  @Facturado    decimal(18,2),
  @Itbis	decimal(18,2),
  @Pagado       decimal(18,2),
  @Amortizado   decimal(18,2),
  @BalAvance decimal(18,2),
  @BalComprometido decimal(18,2),
  @BalFacturado    decimal(18,2),
  @TotalPagado       decimal(18,2)
--set @idContrato = '{5819A19A-FCDB-43AE-979B-AB9937F19A2D}'
Set  @Comprometido = (Select Sum(Valor) From ContCompromiso where idContrato = @idContrato)
Set  @Avanzado = (Select Sum(Valor) From ContAvance where idContrato = @idContrato)
Set  @Facturado = (Select Sum(Valor) From ContDocumento where idContrato = @idContrato)
Set  @Pagado = (Select Sum(Valor) From ContPago where Amortizacion = 0 and idContrato = @idContrato)
Set  @Amortizado = (Select Sum(Valor) From ContPago where Amortizacion = 0 and idContrato = @idContrato)
Set  @Itbis = (Select Sum(Itbis) From ContDocumento where idContrato = @idContrato)
Set  @BalAvance = (@Avanzado-@Amortizado)
Set  @BalComprometido = (@Comprometido-@Facturado)
Set  @BalFacturado = ((@Facturado-@Pagado-@Amortizado) + @Itbis)
Set  @TotalPagado = (@Amortizado+@Pagado)
Select 
  @idContrato as idContrato,
  @Comprometido as Compromiso, 
  @Avanzado as Avances, 
  @Facturado as Facturado, 
  @Itbis as Itbis, 
  @Pagado as Pagado, 
  @Amortizado as Amortizado, 
  @BalAvance as AvanceporLiquidar, 
  @BalComprometido as BalanceCompromiso, 
  @BalFacturado as BalanceFacturacion, 
  @TotalPagado as TotalPagadp

CREATE Procedure [dbo].[maNotificacionRecurrente] as

DECLARE   
  @ID uniqueidentifier,
  @To varchar(500),
  @Subject varchar(100),
  @Comando varchar(100),    
  @Query varchar(max),
  @sql nvarchar(MAX),
  @Body nvarchar(max),   
  @ParmDefinition nvarchar(500);

SET @ParmDefinition = N'@tableHTML nvarchar(max) OUTPUT';

DECLARE Notificaciones CURSOR FOR 
SELECT 
  ID,
  Receptores,
  Titulo,
  Detalle,    
  Comando,
  Query  
FROM 
  maNotificacion
WHERE 
  getdate() > DATEADD(HOUR, FrecuenciaHoras, isnull(ultimacorrida, FrecuenciaHoras))
  and activa = 1       
union
  SELECT 
 -- DATEADD(MINUTE, FrecuenciaMinutos, isnull(ultimacorrida, FrecuenciaMinutos)),getdate() ,
  ID,
  Receptores,
  Titulo,
  Detalle,    
  Comando,
  Query  
FROM 
  maNotificacion
WHERE 
  getdate() > DATEADD(MINUTE, FrecuenciaMinutos, isnull(ultimacorrida, FrecuenciaMinutos))
  and activa = 1 
  
OPEN Notificaciones

FETCH NEXT FROM Notificaciones
INTO @ID,
     @To,
     @Subject,
     @Body,    
     @Comando,
	 @Query

WHILE @@FETCH_STATUS = 0 BEGIN
  
  if @Comando is not null begin

    Set @sql = N'EXEC ' + @Comando + ' @tableHTML OUTPUT'
    EXEC sp_executesql @SQL, @ParmDefinition, @tableHTML=@Body OUTPUT;
	
	if @body is not null
	  exec maCreateMail @to, @Subject, @Body, @Query  	

  end else begin
    exec maCreateMail @to, @Subject, @Body, @Query  
  end
  
  update maNotificacion
  Set ultimacorrida =  Getdate()
  Where ID = @id
  
  FETCH NEXT FROM Notificaciones
  INTO @ID,
       @To,
       @Subject,
       @Body,    
       @Comando,
       @Query

END 
CLOSE Notificaciones;
DEALLOCATE Notificaciones;

CREATE PROCEDURE [dbo].[cxpGuardarSolicitud]
 @idSol int,
 @Num int output,
 @Fec datetime,
 @IdEnt int,
 @Nombre varchar(100), 
 @Valr money,
 @Conc varchar(6000),
 @St char(1),
 @Usuario varchar(30),
 @FechaReg datetime,
 @ValidadoPor varchar(30),
 @validadoEn datetime,
 @revpor varchar(30),
 @reven datetime,
 @valfinal varchar(30),
 @valfinalen datetime,
 @NotaAdicional varchar(100),
 @MostrarEnCXP bit,
 @GUIDSolicitud uniqueidentifier,
 @nid int output,
 @tasa decimal(18,2) ,
 @idCuentaBanco int,
 @idMoneda int,
 @TipoAbono char(1),
 @BancoDestino varchar(5),
 @CuentaDestino varchar(20),
 @TipoSolicitud int,
 @idCuentaBancoDestino int,
 @idOrden uniqueidentifier,
 @OrdenCompra varchar(16),
 @idPagoForma INT = 2 
AS

 declare @idSuplidor int,
	    -- @idMoneda int,
         @TipoProveedor int

 Set @TipoProveedor = (select convert(int,valor) from defaults where clave = '#PROVEEDORLOCAL')

 /*
select top 1 @idMoneda = idMoneda
 from moneda 
 where cursolegal = 1
*/
 if @idEnt <= 0
   begin
	 insert into cxpSuplidores (Nombre,TipoSuplidor, idMoneda, MostrarEnCXP,Estatus)
	   values (@Nombre, @TipoProveedor, @idMoneda, @MostrarEnCXP,1)
	 set @idSuplidor = @@IDENTITY
   end
 else
   set @idSuplidor = @idEnt

 if (coalesce(@idSol,0) = 0)
 begin
   set @Num = coalesce((select max(Numero) 
			from cxpSolicitudes),0) + 1
   insert into cxpSolicitudes (	Numero, 				
				Fecha,
				idSuplidor,
				Total,
				Concepto,
				Status,
				Usuario, FechaRegistro, ValidadaPor, ValidadaEn,
				RevisadaPor, RevisadaEn, ValidadaFinalPor, ValidadaFinalEn,
				NotaAdicional,
				MostrarEnCXP,
	        		GUIDSolicitud,
				Tasa,
				idCuentabanco, idMoneda,
			    TipoAbono, BancoDestino, 
				CuentaDestino, TipoSolicitud, idCuentaBancoDestino, OrdenCompra, idOrden,
				IdPagoForma)
   values (@Num, @Fec, @idSuplidor, @Valr, @Conc, @St, @usuario, @fechaReg,
	         @ValidadoPor, @ValidadoEn, @RevPor, @RevEn, @ValFinal, @ValFinalEn,
           @NotaAdicional, @MostrarEnCXP, @GUIDSolicitud, @Tasa, @idCuentabanco, @idMoneda,
	       @TipoAbono, @BancoDestino, @CuentaDestino, @TipoSolicitud, @idCuentaBancoDestino, 
		   @OrdenCompra, @idOrden, @IdPagoForma)
   set @nid = @@IDENTITY
 end
 else 
 begin
   update cxpSolicitudes
     set Fecha = @Fec,
 	       idSuplidor = @idSuplidor,
	       Total = @Valr,
	       Concepto = @Conc,
	       Status = @st,
	       Usuario = @usuario,
	       FechaRegistro = @FechaReg,
	       ValidadaPor = @ValidadoPor,
	       ValidadaEn = @ValidadoEn,
	       RevisadaPor = @RevPor,
	       RevisadaEn = @RevEn,
	       ValidadaFinalPor = @ValFinal,
	       ValidadaFinalEn = @ValFinalEn,
	       NotaAdicional = @NotaAdicional,
 		   MostrarEnCXP = @MostrarEnCXP,
	       GUIDSolicitud = @GUIDSolicitud,
		Tasa = @Tasa ,
		idCuentabanco = @idCuentabanco,
		idMoneda = @idMoneda,
		TipoAbono = @TipoAbono, 
		BancoDestino = @BancoDestino, 
		CuentaDestino = @CuentaDestino, 
		TipoSolicitud = @TipoSolicitud,
	    idCuentaBancoDestino = @idCuentaBancoDestino,
               OrdenCompra= @OrdenCompra,
               idOrden = @idOrden, 
			   IdPagoForma = @idPagoForma
   where idSolicitud = @idSol
   set @nid = @idSol
 end
return @@ERROR

