CREATE procedure [dbo].[rcgConsolidarDescuentosPlanilla] --'906A1067-00F5-4EA6-8C85-2217F53AA23D','DE9DEA12-BBFA-4072-B9A5-2EA80FEDDD09','10/06/2010'   

--Declare

 @idProyecto uniqueidentifier,    
 @idAjustero uniqueidentifier,     
 @hasta datetime     
 
-- set @idProyecto = '906A1067-00F5-4EA6-8C85-2217F53AA23D'
-- set @idAjustero = 'DE9DEA12-BBFA-4072-B9A5-2EA80FEDDD09'
-- set @hasta  = '10/06/2010'    
 
as
  declare @desde datetime    
    
    
  select top 1 @desde = fecha    
  from rcgReportePago
  where estado = 'A' and fecha <= @hasta  and idProyecto = @idproyecto and idAjustero = @idAjustero
  order by Fecha  
  
  --update rcgReportePago set estado='CONSOLIDADO' WHERE REPORTE=00000201
  --update rcgReportePago set estado='A' WHERE REPORTE=00000201

    
  declare @totalafp decimal(19,2),    
 @totalsfs decimal(19,2),    
 @totalLaboral decimal(19,2),    
 @infotep decimal(19,2)    
    
select @totalafp = sum(d.afp),    
       @totalsfs = sum(d.sfs),    
       @totallaboral = sum(dbo.rcgCalcRiesgoLaboral(d.HorasNormales, d.HorasExtras, d.Jornal)) ,    
       @infotep = sum(dbo.rcgCalcInfotep(d.HorasNormales, d.HorasExtras, d.Jornal))      
from rcgPlanillaNomina p    
join rcgPlanillaNominaDet d on p.idPlanillaNomina = d.idPlanillaNomina     
where p.idProyecto = @idproyecto and p.idAjustero = @idAjustero    
and p.Fechapago between @desde and @hasta  
    
 select round(isnull(@totalafp,0.00) / 0.4287729196050776,2) as AFP,    
        round(isnull(@totalsfs,0.00) / 0.4042253521126761,2) as SFS,    
        @totalLaboral as RiesgoLaboral,    
        Otros = isnull(@totalafp,0.00) + isnull(@totalsfs,0.00) ,   
 isnull(@infotep,0.00) as Infotep,@desde

