CREATE Procedure [dbo].[nomPrestaciones](@EmpleadoId Int,             
                                 @FechaFin DateTime,             
                                 @TomoVacaciones Bit,            
                                 @Preaviso Bit,            
                                 @PagarRegalia Bit)            
AS            
Declare            
  @FechaInicio DateTime,          
  @SalarioActual Numeric(18,2),            
  @SalarioAcum Numeric(18,2),            
  @Anos Int,            
  @Meses Int,            
  @Departamento VarChar(100),            
  @Seccion VarChar(100),            
  @Empleado VarChar(200),            
  @Cedula VarChar(20),            
  @Roll VarChar(100),          
  @TiempoMesTotal Int,          
  @OrigTiempoMesTotal Int,          
  @TiempoAno   Int,            
  @MesesAdc Int,            
  @DiasPreaviso Int,          
  @DiasVacaciones Int,            
  @DiasVacacionesII Int,          
  @DiasCesantiaCodAnt Int,          
  @DiasCesantiaCodActual Int,          
  @Codigo VarChar(20)  ,        
  @dias int, @origMeses int,      
  @origAnos int, @origDias int         
          
Set          
  @Codigo = (Select IsNull(Convert(VarChar(20), Valor), '') From Defaults Where Clave = 'CodFPrestacion')          
If @Codigo <> ''          
Begin          
  Set          
    @Codigo = 'Código:   ' + @Codigo          
End          
Select            
  @FechaInicio = Inicio,          
  @SalarioActual = SueldoMes,          
  @Departamento = d.Departamento,            
  @Seccion = s.Seccion,            
  @Empleado = Empleado,            
  @Cedula = Cedula,            
  @Roll = r.EmpleadoRoll            
From            
  Empleado     e Inner Join            
  Departamento d On (d.DepartamentoId = e.DepartamentoId) Inner Join            
  Seccion      s On (s.SeccionId = e.SecionId) Left Outer Join            
  EmpleadoRoll r On (r.IdEmpleadoRoll = e.IdEmpleadoRoll)            
Where            
  EmpleadoId = @EmpleadoId          
        
set @TiempoAno = (dbo.cbsHowManyMonth(@FechaInicio, @FechaFin) / 12)          
set @Anos = @TiempoAno     --(dbo.cbsHowManyMonth(@FechaInicio, @FechaFin) / 12)          
set @Meses = dbo.cbsHowManyMonth(@FechaInicio, @FechaFin) % 12            
set @TiempoMesTotal = dbo.cbsHowManyMonth(@FechaInicio, @FechaFin)          
set @MesesAdc =  dbo.cbsHowManyMonth(DateAdd(Year, @TiempoAno, @FechaInicio), @FechaFin)            
set @dias = datediff(day, dateadd(month, @tiempoMesTotal, @fechaInicio), @FechaFin)        
        
set @OrigMeses = @meses         
set @OrigAnos = @Anos      
set @Origdias = @dias       
set @OrigTiempoMesTotal = @TiempoMesTotal    
        
if @dias > 15 begin        
  set @meses = @Meses + 1        
  set @MesesAdc = @MesesAdc + 1        
  set @TiempoMesTotal = @TiempoMesTotal + 1         
  set @dias = 0        
  if @meses >= 12 begin      
    set @meses = @meses - 12      
    set @TiempoAno = @TiempoAno + 1      
    --set @TiempoMesTotal = @TiempoMesTotal + 1      
    --set @mesesAdc = @mesesAdc + 1       
    set @anos = @anos + 1        
  end      
end        
--print 'MESES    = ' + convert(varchar(30), @Meses) + char(13) +        
--      'MESESADC = ' + convert(varchar(30), @MesesAdc) + char(13) +        
--      'DIAS     = ' + convert(varchar(30), @dias) + char(13)         
        
Exec          
  nomDiasCesantia @EmpleadoId, @FechaFin, @DiasCesantiaCodAnt OutPut, @DiasCesantiaCodActual OutPut          
Select              
  @DiasPreaviso = CASE              
      When @TiempoMesTotal >= 12 Then              
                      28              
      When @TiempoMesTotal >= 06 Then              
               14              
      When @TiempoMesTotal >= 03 Then              
                      07              
                    Else              
                      00              
     END              
Select            
  @DiasVacaciones = CASE            
        When @OrigTiempoMesTotal >= 60 Then            
                  18            
        When @OrigTiempoMesTotal >= 12 Then            
       14            
        When @OrigTiempoMesTotal >= 05 Then            
                  @TiempoMesTotal + 1            
        Else            
                  0            
        END            
Select            
  @DiasVacacionesII = CASE            
          When @MesesAdc >= 11 Then            
                   12            
            When @MesesAdc >= 10 Then            
                   11            
          When @MesesAdc >= 09 Then            
                   10            
          When @MesesAdc >= 08 Then            
                   09            
          When @MesesAdc >= 07 Then            
                   08            
          When @MesesAdc >= 06 Then            
                   07            
          When @MesesAdc >= 05 Then            
                   06            
          Else            
                   00            
          END            
SELECT                 
  @SalarioAcum = SUM(t.Transaccion)            
FROM                     
  Empleado e INNER JOIN            
  Transaccion t ON e.EmpleadoID = t.EmpleadoID INNER JOIN            
  TipoTransaccion tt ON t.TipoTransaccionID = tt.TipoTransaccionID INNER JOIN            
  Nomina n ON t.NominaID = n.NominaID            
WHERE            
  e.EmpleadoId = @EmpleadoId AND            
--  tt.TipotransaccionID In (Select TipoTransaccionId From TipoTransaccion Where Debito = 1 And IsrNo = 0 And Cotizable = 1) AND            
  tt.TipotransaccionID In (Select TipoTransaccionId From vTransInPrestaciones) AND            
  n.Fecha Between DateAdd(Month, -12, @FechaFin) And @FechaFin         
    
declare @PromedioDia decimal(19,2)    
--select @PromedioDia = Case When @Anos >= 1 Then @SalarioAcum / 12 Else @SalarioAcum  / @Meses End    
  select @PromedioDia = Case When @Anos >= 1 Then ((@SalarioAcum / 12) / 23.83) Else ((@SalarioAcum  / @Meses) / 23.83) End     
SELECT            
  @Empleado As Empleado,            
  @FechaInicio As FechaInicio,          
  @FechaFin As FechaFin,          
  @SalarioActual As SalarioActual,            
  @SalarioAcum As Acumulado12Meses,          
  Case When @Anos >= 1 Then @SalarioAcum / 12 Else @SalarioAcum  / @Meses End As SalarioPromedioMensual,          
  Case When @Anos >= 1 Then ((@SalarioAcum / 12) / 23.83) Else ((@SalarioAcum  / @Meses) / 23.83) End As SalarioPromedioDiario,          
  @PromedioDia as SalarioPromedioDiario,          
  @DiasPreaviso As DiasPreaviso,          
  @DiasCesantiaCodAnt As DiasCesantiaCodAnt,          
  @DiasCesantiaCodActual AS DiasCesantiaCodActual,          
  @DiasVacaciones As DiasVacaciones,          
  Month(@FechaFin) AS DiasRegalia,          
  @Anos As Ano,            
  @Meses As Meses,            
  @Dias as Dias,         
  @OrigMeses as OrigMeses,         
  @OrigDias as OrigDias,      
  @OrigAnos as origAnos,       
  @Departamento As Departamento,            
  @Seccion As Seccion,            
  @Cedula As Cedula,            
  @Roll As Roll,            
  Case            
    When @Preaviso = 1 Then            
      0.00            
    Else    
      @DiasPreaviso * @PromedioDia      
      --dbo.nomPreaviso(@EmpleadoId, @FechaFin)            
  End As Preaviso,            
  dbo.nomCesantiaPromedio(@EmpleadoId, @FechaFin, @PromedioDia) As Cesantia,              
  dbo.nomVacaciones(@EmpleadoId, @FechaFin, @TomoVacaciones) As Vacaciones,              
  Case            
    When @PagarRegalia = 1 Then            
      dbo.nomRegalia(@EmpleadoId, @FechaFin)            
    Else            
      0.00            
  End As Regalia,            
  Total = Case When @Preaviso = 1 Then 0.00 Else (@PromedioDia * @DiasPreaviso) end +             
          dbo.nomCesantiaPromedio(@EmpleadoId, @FechaFin, @PromedioDia) +            
          dbo.nomVacaciones(@EmpleadoId, @FechaFin, @TomoVacaciones) +             
          Case When @PagarRegalia = 1 Then dbo.nomRegalia(@EmpleadoId, @FechaFin) Else 0.00 End,    
  @Codigo As CodigoForm

