CREATE Procedure [dbo].[NomResumenTransRpt](@NominaId Int)
AS
Declare
  @Desde DateTime,
  @Hasta DateTime,
  @TipoEmpleado VarChar(20),
  @CantEmpleado Int
Select
  @Desde = Desde,
  @Hasta = Hasta,
  @TipoEmpleado = TipoEmpleado
From
  Nomina       no Inner Join
  TipoEmpleado te On (no.TipoEmpleadoId = te.TipoEmpleadoId)
Where
  no.NominaId = @NominaId

Select @CantEmpleado = Count(*) From NominaEmp Where NominaId = @NominaId

--******
SELECT
  @NominaId As NominaId,
  @Desde As Desde,
  @Hasta As Hasta,
  @TipoEmpleado As TipoEmpleado,
  @CantEmpleado As CantEmpleado,
  TipoTransaccionId,
  TipoTransaccion,
  Debito,
  SUM(Case When tr.Debito = 0 Then (tr.Transaccion * -1) Else tr.Transaccion End) AS Valor, 
  SUM(tr.XCantidad)   AS Cantidad
FROM
  Transacciones tr Inner Join
  NominaEmp     ne On (tr.NominaId = ne.NominaId And tr.EmpleadoId = ne.EmpleadoId)
WHERE
  ne.NominaId = @NominaId
GROUP BY
  TipoTransaccionId,
  TipoTransaccion,
  Debito
ORDER BY
  tr.TipoTransaccion

