CREATE PROCEDURE [dbo].[InsCalCantidad] (
  @Cantidad numeric(18,4), 
  @idGama varchar(16), 
  @idGfh varchar(16), 
  @idCalendario varchar(16)
)
AS
declare
  @Visita bit,
  @Gamas varchar(100),
  @OTEjecutor varchar(16),
  @OTIntervencion varchar(16),
  @Costo numeric(18,2),
  @TipoCalendario Varchar(10),
  @Secuencia varchar(16)

Select Top 1 
   @Visita = Visita,
   @Gamas = Gama,
   @OTEjecutor = OTEjecutor,
   @OTIntervencion = OTIntervencion
From 
  Gama 
Where 
  idGama = @idGama

Select Top 1
  @TipoCalendario = Tipo
From
  Calendario
Where
  idCalendario = @idCalendario
 
  Exec spGetNextCounterSTR 'GAMAS',@OutPut = @Secuencia OutPut
  INSERT INTO Gamas (CodGamas, idCalendario, idGama, idGFH, Cantidad, CantidadOriginal, GamaStatus, Visita, Gamas, OTEjecutor, OTIntervencion, Pospuesto, TipoCalendario)
  VALUES(@Secuencia, @idCalendario, @idGama, @idGFH, @Cantidad,@Cantidad,  1, @Visita, @Gamas, @OTEjecutor, @OTIntervencion, 0, @TipoCalendario)

CREATE PROCEDURE [dbo].[InsCalFecha] (
  @Fecha datetime, 
  @idGama varchar(16), 
  @idGFH varchar(16), 
  @idCalendario varchar(16)
)
AS
declare
  @Visita bit,
  @Gamas varchar(100),
  @OTEjecutor varchar(16),
  @OTIntervencion varchar(16),
  @Costo numeric(18,2),
  @TipoCalendario varchar(10),
  @Secuencia varchar(16)

Select Top 1 
   @Visita = Visita,
   @Gamas = Gama,
   @OTEjecutor = OTEjecutor,
   @OTIntervencion = OTIntervencion
From 
  Gama 
Where 
  idGama = @idGama

Select Top 1
  @TipoCalendario = Tipo
From
  Calendario
Where
  idCalendario = @idCalendario

-- para que no se repotan gamas iguales con la misma fecha para el mismo gfh se usa este if
If NOT EXISTS (Select top 1 1 from gamas g where g.idgama = @idGama and g.idgfh = @idGfh and g.Fecha = @Fecha)
BEGIN
   Exec spGetNextCounterSTR 'GAMAS',@OutPut = @Secuencia OutPut
  INSERT INTO Gamas (CodGamas, idCalendario, idGama, idGFH, Fecha, FechaOriginal, GamaStatus, Visita, Gamas, OTEjecutor, OTIntervencion, Pospuesto, TipoCalendario)
  VALUES (@Secuencia, @idCalendario, @idGama, @idGFH, @Fecha, @Fecha, 1, @Visita, @Gamas, @OTEjecutor, @OTIntervencion, 0, @TipoCalendario)
END

