CREATE   procedure [dbo].[eduDatosEstado]
--declare 
 @idCli int, 
 @Fec datetime,
 @esFamilia datetime
as
declare 
 @Bal decimal(19,2) ,
 @PorDist decimal(19,2),
 @FechaUltCargo datetime ,
 @RefUltCargo varchar(20) ,  
 @TipoUltCargo varchar(10) ,
 @MtoUltCargo decimal(19,2) ,
 @FechaUltPago datetime ,
 @RefUltPago varchar(20) , 
 @MtoUltPago decimal(19,2) 
--as
 set @Bal = dbo.cxcBalanceClienteVencimiento(@idCli, @Fec)
 set @PorDist = dbo.cxcCreditoporDist(@idCli, @Fec)
 if @esFamilia = 1 begin
  select top 1 
    @FechaUltCargo = f.Fecha,
    @RefUltCargo = f.CXC,
    @TipoUltCargo = f.idTipoDocumento,
    @MtoUltCargo = f.Valor
  from 
    CXC f 
    join Cliente c on f.idCliente = c.idcliente
  where 	
    (c.idClienteParent = @idCli or c.idCliente = @idCli) 
    and f.Fecha <= @Fec
    and f.esCredito = 0
  order by 
    f.fecha desc, 
    f.CXC desc 
  select top 1 
    @FechaUltPago = r.Fecha,
    @RefUltPago = r.CXC,
    @MtoUltPago = r.Valor
  from 
    CXC r 
    join Cliente c on r.idCliente = c.idcliente      
  where
    EsCredito = 1
    and (c.idClienteParent = @idCli or r.idCliente = @idCli)
    and r.Fecha <= @Fec 
  order by 
    fecha desc, CXC desc 
end else begin
 select top 1 
	@FechaUltCargo = f.Fecha,
	@RefUltCargo = f.CXC,
	@TipoUltCargo = f.idTipoDocumento,
	@MtoUltCargo = f.Valor
  from 
    CXC f 
  where 	
    f.idCliente = @idCli 
    and f.Fecha <= @Fec
    and f.esCredito = 0
 order by 
    f.fecha desc, 
    f.CXC desc 
 select top 1 
	@FechaUltPago = r.Fecha,
	@RefUltPago = r.CXC,
	@MtoUltPago = r.Valor
  from CXC r 
where 	EsCredito = 1
	and r.idCliente = @idCli 
	and r.Fecha <= @Fec 
 order by fecha desc, CXC desc 
end
select 	@Bal as Balance, 
        @PorDist as PorDist,
 	@FechaUltCargo as FecUltCargo,
	@RefUltCargo as RefUltCargo,  
	@TipoUltCargo as TipoUltCargo, 
 	@MtoUltCargo as MtoUltCargo,
	@FechaUltPago as FecUltPago,
	@RefUltPago as RefUltPago, 
	@MtoUltPago as MtoUltPago 
--return 0

