 @Fec datetime
as
-- Procedure Name : bcoGuardarStatusDoc
-- Created By : Jorge
-- Created On : 20/12/2004 3:37:26 PM
begin
-- local variables
  declare @ck varchar(3),
	  @Orig int,
	  @oldst char(1),
	  @fecst datetime
	-- set nocount on and default isolation level
    set nocount on
    set transaction isolation level Read Committed
    select @ck = TipoDocOrigen,
	   @Orig = DocOrigen,
	   @oldst = Status,
	   @fecst = FechaStatus 
    from bcoDocumentos 
     where GUIDDocumento = @idDoc
