CREATE   Procedure [dbo].[eduGenCargosExtra](@idCliente int, @Fecha datetime, @Valor decimal(18,2), @Concepto varchar(150), @Usuario varchar(30), @idcxctipo int) as

declare 
  @TipoDocDesc varchar(16),
  @error int,
  @Cliente varchar(60),
  @ClienteParent varchar(60),
  @idClienteParent int,
  @uidCliente uniqueidentifier


set @Error = 0

set @TipoDocDesc = left((select CxcTipo from CxcTipo where idCxcTipo = @idCXCTipo),16)

  select 
    @Cliente = c.Cliente,
    @ClienteParent = cc.Cliente,
    @idClienteParent = cc.idCliente,
    @uidCliente = c.uidCliente
  FROM         
    dbo.Cliente c
    Left join Cliente cc on c.idClienteParent = cc.idCliente    
  where
    c.idCliente = @idCliente

  if @@rowcount = 0 begin
     Return -1 
  end
  begin tran
  insert into cxc (idcxc, cxc, idcliente, cliente, idtipodocumento, valor, fecha, concepto, idcxctipo, 
                   escredito, cancelado, usuario, Descuento, Condicion, Vencimiento, idMoneda, Tasa, Referencia)
  select 
    newid(),
    @TipoDocDesc,
    CASE WHEN @idClienteParent is NULL THEN @idCliente ELSE @idClienteParent END,
    CASE WHEN @idClienteParent is NULL THEN @Cliente   ELSE @ClienteParent   END,
    'ND',
    @Valor,
    @Fecha,
    convert(varchar(100), @Concepto + @Cliente),
    @idCXCTipo, --idcxcTipo
    0, --esCredito
    0, --cancelado
    @usuario,
    0.00,
    0,   --Condicion
    @Fecha,
    1,
    1 as tasa,
    @uidCliente

  Set @Error = @@Error
  if @Error <> 0 begin
    Rollback tran
    Return @Error 
  end
commit tran

