  @Uno bit,  
  @PorcentajeMes1 numeric(18,2),  
  @DescMensual decimal(18,2),  
  @DescInscrip decimal(18,2),  
  @NewIdCxc UniqueIdentifier  
Set @uno = 1  
set @Error = 0  
set @TipoDoc = 'ND' --Tipo de Cargo para Cargos de Estudiantes''  

  select   
    @Inicial = (CASE WHEN i.FechaPago > p.Inicio THEN i.FechaPago ELSE p.inicio END),  
    @Final   = p.Final,  
    @idCliente = c.idCliente,  
    @uidCliente = c.uidCliente,  
    @Cliente = c.Cliente,  
    @idClienteParent = cc.idCliente,  
    @ClienteParent = cc.Cliente,  
    @Inscripcion = i.Inscripcion,  
    @Mensualidad = i.Mensualidad,  
    @FechaInscripcion = i.fechaInscripcion,  
    @Usuario = i.usuario,  
    @Curso = cu.Curso,  
    @PorcentajeMes1 = i.PorcentajeMes1,  
    @DescMensual = i.DescuentoMensual,  
    @DescInscrip = i.DescuentoInscripcion  
  FROM           
    dbo.eduInscripcion i   
    INNER JOIN dbo.eduCurso cu ON i.idCurso = cu.idCurso   
    INNER JOIN dbo.eduPeriodo p ON cu.idPeriodo = p.idPeriodo   
    INNER JOIN dbo.Cliente c ON i.idCliente = c.idCliente  
    INNER JOIN cliente cc on c.idClienteparent = cc.idCliente  
  where  
    i.idInscripcion = @idInscripcion  
  
  if @@rowcount = 0 begin  
     Return -1   
  end  
  begin tran  
  
  Set @NewIdCxc = NewId()  
  
  insert into cxc (idcxc, cxc, idcliente, cliente, idtipodocumento, valor, fecha, concepto, idcxctipo, escredito, cancelado, referencia, idReferencia, usuario, Descuento, Condicion, Vencimiento, CompFiscal, idMoneda, Tasa)  
  select   
    @NewIdCxc,  
    'INSCRIPCION',  
    @idClienteParent,  
    @ClienteParent,  
    @TipoDoc,  
    (@Inscripcion - (@Inscripcion * (@DescInscrip/100))),  
--    @Inscripcion,  
    @FechaInscripcion,  
    'INSCRIP. '+ @Cliente,  
    5, --idcxcTipo  
    0, --esCredito  
    0, --cancelado  
    @uidCliente,  
    @idInscripcion,  
    @usuario,  
    0.00,  
    0,   --Condicion  
    @FechaInscripcion,  
    NULL,  
    1,  
    1  
  where  
    @inscripcion > 0  
  
  -- Exec   
  --   eduGenNCEnInscripcion @NewIdCxc, @IdInscripcion  
  
  Set @Error = @@Error  
  if @Error <> 0 begin  
    Rollback tran  
    Return @Error   
  end  
  WHILE @inicial <= @Final BEGIN  
    Set @FechaCargo = (Select dbo.inicioMes(@inicial))  
    Set @NewIdCxc = NewId()  
  
     insert into cxc (idcxc, cxc, idcliente, cliente, idtipodocumento, valor, fecha, concepto, idcxctipo, escredito, cancelado, referencia, idreferencia, usuario, Descuento, Condicion, Vencimiento, CompFiscal, idMoneda, Tasa)  
     select    
       @NewIdCxc,  
       'MES ' + convert(varchar, @FechaCargo, 104),  
       @idClienteParent,  
       @ClienteParent,  
       @TipoDoc,  
       Convert(decimal(18,2), (Case when @Uno = 1 then 
          @Mensualidad-(@Mensualidad *(@DescMensual/100))- (@Mensualidad * (@PorcentajeMes1/100)) 
        else
          @Mensualidad-@Mensualidad *(@DescMensual/100) 
       end)),  
       @FechaInscripcion,  
       'MES ' + convert(varchar, @FechaCargo, 104) + ' - ' + @Cliente,  
       6, --idcxcTipo  
       0, --esCredito  
       0, --cancelado  
       @uidCliente,  
       @idInscripcion,  
       @usuario,  
       0.00,  
       0,   --Condicion  
       @FechaCargo,  
       NULL,  
       1,  
       1  
     where  
--        Convert(decimal(18,2),Case when @Uno = 1 then (convert(decimal(18,2),(@Mensualidad -(@Mensualidad*(@DescMensual/100)))) * (@PorcentajeMes1/100)) else convert(decimal(18,2),(@Mensualidad -(@Mensualidad*(@DescMensual/100)))) end ) > 0  
       @Mensualidad > 0  
  
-- Aqui llamada al procedimiento que genera las notas de creditos por los descuentos   
--     Exec   
--       eduGenNCEnInscripcionMes @NewIdCxc, @IdInscripcion, @Uno  
  
     Set @Error = @@Error  
     if @Error <> 0 begin  
       Rollback tran  
       Return @Error   
     end  
     Set @Uno = 0  
     Set @Inicial = dateadd(m, 1, @Inicial)  
  END  
commit tran

