CREATE Procedure [dbo].[InvRequisicionAlmCreate]
 @Departamento VarChar(16),   
 @Solicitante VarChar(50),   
 @Referencia VarChar(16),   
 @Usuario VarChar(30),  
 @Nota VarChar(200),  
 @FechaRequerido DateTime,  
 @uIdReferencia UniqueIdentifier, 
 @IdReqOutPut  UniqueIdentifier OutPut   
AS  
Declare  
  @InvReq VarChar(16),  
  @IdReq UniqueIdentifier,  
  @Fecha DateTime  
  
If Exists(Select Top 1 1 From InvReq Where uIdReferencia = @uIdReferencia)  
Begin  
  Return 1  
End  
  
Set  
  @IdReq = NewId()    
  
Exec  
  spGetNextCounterSTR 'REQUISICIONALM', @InvReq OutPut  
  
Set  
  @Fecha = (Select Convert(DateTime, Round(Convert(Float, GetDate()), 0, 1)))  
  
--Begin Tran  
  Insert Into  
    InvReq (IdInvReq, InvReq, Fecha, Departamento, Solicitante, Referencia, 
            InvReqStatus, Usuario, Nota, FechaRequerido, uIdReferencia)  
  Values   (@IdReq, @InvReq, @Fecha, @Departamento, @Solicitante, @Referencia, 
            'Requerido', @Usuario, @Nota, IsNull(@FechaRequerido, @Fecha), @uIdReferencia)  
--Commit Tran  
  
Set  
  @IdReqOutPut = @IdReq  
  
Return 0

create procedure [dbo].[cgMovimientoAuxiliarCta] 
 @idCta varchar(16), 
 @idAux varchar(16), 
 @desde datetime, 
 @hasta datetime,
 @TDB decimal(19,2) output,
 @TCR decimal(19,2) output
as 
begin
	select 	@TDB = sum(Debito),
					@TCR = sum(Credito)
	from cgEntradasDetalle d join cgEntradasDiario e
	   on d.IdEntrada = e.IdEntrada
	where idCuenta = @idCta
		    and idAuxiliar = @idAux
				and Fecha between @desde and @hasta

	select @TDB = isnull(@TDB,0.00),
	       @TCR = isnull(@TCR,0.00)
end
return 0

create Procedure [dbo].[presGenerarCuotasSol](@idSolicitud int) as

 DECLARE
      @Monto Numeric(18,2),
      @Fecha datetime,
      @FechaCuota datetime,
      @Interes Numeric(18,2),
      @Cuotas decimal(18,2),
      @Frecuencia varchar(16),
      @Tipo varchar(50),
      @porMes Numeric(18,2),
      @Dias Numeric(18,2),
      @i integer   
      
  Select
    @Monto             = p.MontoSolicitado + (CASE WHEN p.CapitalizarCierre = 1 THEN p.CargoCierre ELSE 0.00 END),
    @Fecha             = p.Fecha,
    @Interes           = p.Interes,
    @Cuotas            = p.Cuotas,
    @Frecuencia        = p.Frecuencia,
    @Tipo              = p.Tipo,
    @porMes			   = f.PorMes,
    @Dias              = f.Dias    
  From
    presSolicitud p 
    join presFrecuencia f on p.frecuencia = f.frecuencia
  Where
    idSolicitud = @IdSolicitud
    
  delete 
  from pressolicituddet
  where idsolicitud = @idSolicitud     

  Exec presGenPrestamoCuotas @idSolicitud, 1,  @Monto, @Fecha, @Interes, @Cuotas, @Frecuencia, @Tipo

  
  if (select Redito from presprestamoTipo where Tipo = @Tipo) = 1 begin
  
    Set @FechaCuota = @Fecha 
    Set @i = 1
   
   while @i <= @cuotas begin
     
     if @porMes = 1 begin
       Set @FechaCuota = dateadd(m, 1, @FechaCuota)
     end else begin
       Set @FechaCuota = dateadd(d, @Dias, @FechaCuota) 
     end   
   
     Insert Into presSolicitudDet (Transaccion, idSolicitud, DebCre, Interes, Capital, Monto, IdTipo, Fecha, Cancelado)
     Values ('INTERES', @idSolicitud, 1, (((@Interes / @porMes) / 100.00) * @Monto), 0.00, (((@Interes / @porMes) / 100.00) * @Monto), 'INTERES', @FechaCuota, 0)   
   
     Set @i = @i + 1
     
   end 
  end
  
  return 0

create procedure [dbo].[cgResumenBalanza] 
 @fec datetime
as
 declare @TotalActivos decimal(19,2),
	 @TotalPasivos decimal(19,2),
	 @TotalCapital decimal(19,2),
	 @TotalIngresos decimal(19,2),
	 @TotalCostos decimal(19,2),
	 @TotalGastos decimal(19,2)
 select	@TotalActivos = dbo.cgBalanceCtaOrigen('1',@fec, 'D'),
	@TotalPasivos = dbo.cgBalanceCtaOrigen('2',@fec, 'C'),
	@TotalCapital = dbo.cgBalanceCtaOrigen('3',@fec, 'C'),
	@TotalIngresos = dbo.cgBalanceCtaOrigen('4',@fec, 'C'),
	@TotalCostos = dbo.cgBalanceCtaOrigen('5',@fec, 'D'),
	@TotalGastos = dbo.cgBalanceCtaOrigen('6',@fec, 'D') + dbo.cgBalanceCtaOrigen('7',@fec, 'D')
 
 select	TotalActivos = @TotalActivos,
	TotalPasivos = @TotalPasivos ,
	TotalCapital = @TotalCapital ,
	TotalIngresos = @TotalIngresos ,
	TotalCostos = @TotalCostos ,
	TotalGastos = @TotalGastos,
	PruebaCero = (@TotalActivos - (@TotalPasivos + @TotalCapital)) - (@TotalIngresos - (@TotalCostos + @TotalGastos))
	
return 0

