Create Function [dbo].[nomDiasPorNomina](@EmpleadoId Int, @NominaId Int)
Returns Numeric(18,2)
AS
BEGIN
  Declare
    @Inicio DateTime,
    @Fin    DateTime,
    @DesdeCalc DateTime,
    @HastaCalc DateTime,
    @Resultado Numeric(18,2),
    @DiasPorNomina Numeric(18,2)

  Declare
    @Desde DateTime,
    @Hasta DateTime

  SELECT
    @Desde = Desde,
    @Hasta = Hasta,
    @DiasPorNomina = t.SalDiasPor
  FROM
    Nomina n Inner Join
    TipoNomina t On (t.TipoNominaId = n.TipoNominaId)
  WHERE
    NominaId = @NominaId
    
   select @Inicio = Inicio,
		  @Fin = Fin
   from empleado
   where EmpleadoId = @EmpleadoID 

  If (@Inicio <= @Desde) and (IsNull(@Fin, @Hasta) >= @Hasta)
  Begin
    Set
      @Resultado = @DiasPorNomina
  End
  Else
  Begin
    If @Inicio > @Desde
      Set
        @DesdeCalc = @Inicio
    Else
      Set
        @DesdeCalc = @Desde
    If @Fin < @Hasta
      Set
        @HastaCalc = @Fin
    Else
      Set
        @HastaCalc = @Hasta
 
    Set
      @Resultado = DateDiff(day, @DesdeCalc, @HastaCalc) + 1
  End

Return
  @Resultado
END

CREATE Function nomSueldoPorNomina(@EmpleadoId Int, @NominaId Int)
Returns Numeric(18,2)
AS
BEGIN
  Declare
    @Inicio DateTime,
    @Fin    DateTime,
    @SueldoMes Numeric(18,2),
    @Sueldo Numeric(18,2),
    @DesdeCalc DateTime,
    @HastaCalc DateTime,
    @Resultado Numeric(18,2)
  Declare
    @Desde DateTime,
    @Hasta DateTime
  SELECT
    @Desde = Desde,
    @Hasta = Hasta
  FROM
    Nomina
  WHERE
    NominaId = @NominaId
  SELECT
    @Sueldo = e.Sueldo
  FROM
    Empleado e
  WHERE
    EmpleadoId = @EmpleadoId
  If (@Inicio <= @Desde) Or (IsNull(@Fin, @Hasta) >= @Hasta)
  Begin
    Set
      @Resultado = @Sueldo
  End
  Else
  Begin
    If @Inicio > @Desde
      Set
        @DesdeCalc = @Inicio
    Else
      Set
        @DesdeCalc = @Desde
    If @Fin < @Hasta
      Set
        @HastaCalc = @Fin
    Else
      Set
        @HastaCalc = @Hasta
    Set
      @Resultado = ((@SueldoMes*12/52/5) * DateDiff(day, @DesdeCalc, @HastaCalc))
  End
Return
  @Resultado
END

create function [dbo].[ocAutorizable](@idOrden uniqueidentifier,
							 @usuario varchar(30))
returns bit
as 
begin
		
declare @Autorizable bit
set @Autorizable = 0

declare @ST_PEN varchar(16) set @ST_PEN = 'PENDIENTE'
declare @ST_CAN varchar(16) set @ST_CAN = 'CANCELADO'
declare @ST_APR varchar(16) set @ST_APR = 'APROBADO'

declare @apr1 varchar(16),
		@apr1Usr varchar(30),
		@apr2 varchar(16),
		@apr2Usr varchar(30),
		@st char(1),
		@Total decimal(19,2),
		@Limite decimal(19,2)

select	@apr1 = Apr1,
		@apr2 = Apr2,
		@apr1Usr = Apr1Usuario,
		@apr2Usr = Apr2Usuario,
		@Total = GranTotal,
		@st = Status
from ocOrdenes o
where o.idOrden = @idOrden

if isnull(@st,'C') = 'A' begin  
  set @Limite = isnull((select top 1 MontoMaximo from ocLimiteAutorizacion
   					    where Usuario = @Usuario and Activo = 1),0.00)

  if @Total < @Limite begin
    if (@apr1 = @ST_PEN) or (@apr1Usr <> @Usuario)
       set @Autorizable = 1
  end
end

return (@Autorizable)
end

create function [dbo].[cbsHowManyMonthEx] (@fechainicio datetime, @fechafinal datetime)
  returns int
as
begin
	declare
	  @yearHolder int,
	  @dateholder datetime,
	  @counter int

	select
	   @yearholder = datediff(year, @fechainicio, @fechafinal)

	select
	  @dateholder = dateadd(year, @yearholder, @fechainicio)

	set
	  @counter = 0

	While @dateHolder < @fechafinal
	begin
	  select
		@dateHolder = dateadd(month, 1, @dateHolder)
	  if @dateholder <= @fechafinal
	  begin
		set 
		  @counter = @counter + 1
	  end
	end

	return
	  @counter
end

CREATE FUNCTION [dbo].[cgBalanceCta]
	(@Idcta varchar(16), 
	 @Fec datetime)
RETURNS money
AS
BEGIN
declare @Balance money,
	@EstBal money,
	@MovTDB money,
	@MovTCR money,
	@EstFec datetime,
	@inicio datetime
select 	top 1
	@EstFec = FechaCorte, 
	@EstBal = BalanceActual
from cgEstadisticas
where 	idCuenta = @idCta
	and FechaCorte <= @Fec
order by FechaCorte desc
select @inicio = coalesce(dateadd(day,1,@EstFec),'01/01/1900')
select 	@MovTDB = sum(Debito),
	@MovTCR = sum(Credito)
from cgEntradasDetalle d join cgEntradasDiario e
   on d.IdEntrada = e.IdEntrada
where Fecha between @inicio and @Fec and idCuenta like @idCta + '%'
select @Balance = coalesce(@EstBal,$0) + (Coalesce(@MovTDB,$0) - Coalesce(@MovTCR,$))
RETURN @Balance
END

CREATE  FUNCTION [dbo].[cgMovCtaEstat]
	(@Idcta varchar(16), 
	 @Fec datetime,
	 @DebCre tinyint)
RETURNS decimal(19,2)
AS
BEGIN
declare @Balance decimal(19,2),
	@EstTDB decimal(19,2),
	@EstTCR decimal(19,2),
	@MovTDB decimal(19,2),
	@MovTCR decimal(19,2),
	@EstFec datetime,
	@inicio datetime
select 	top 1
	@EstFec = FechaCorte, 
	@EstTCR = TotalCredito,
	@EstTDB = TotalDebito
from cgEstadisticas
where 	idCuenta = @idCta
	and FechaCorte <= @Fec
order by FechaCorte desc
if @EstFec is null or @EstFec < @Fec
begin
select @inicio = coalesce(dateadd(day,1,@EstFec),'01/01/1900')
select 	@MovTDB = sum(Debito),
	@MovTCR = sum(Credito)
from cgEntradasDetalle d join cgEntradasDiario e
   on d.IdEntrada = e.IdEntrada
where Fecha between @inicio and @Fec and idCuenta like @idCta + '%'
end
if @debcre = 1
  select @Balance = coalesce(@EstTDB,0.00) + Coalesce(@MovTDB,$0)
else
  select @Balance = coalesce(@EstTCR,$0) + Coalesce(@MovTCR,$0)
RETURN @Balance
END

CREATE FUNCTION padCurrencyLeft
    (
      @cur DECIMAL(19, 2) ,
      @len INT ,
      @ch CHAR(1)
    )
RETURNS VARCHAR(1000)
AS
    BEGIN
        DECLARE @ret VARCHAR(1000) ,
            @str VARCHAR(30)
	      
        SET @str = CONVERT(VARCHAR(30), ISNULL(@cur, 0.00))
  
        SELECT  @ret = dbo.padStringLeft(@str, @len, @ch)
  
        RETURN @ret
    END

